/**
 * MediVault AI Medical Report Summarization Service
 * Integrates with Google Gemini API using GEMINI_API_KEY / AI_API_KEY
 * Includes an advanced clinical biomarker parser and lab file extractor
 */

import { normalizeExtractedText } from "./pdfExtractionService.js";

const getApiKey = () => (process.env.GEMINI_API_KEY || process.env.AI_API_KEY || "").trim();

const normalizeModel = (model) => {
  if (!model || model === "gemini-flash-lite-latest") {
    return "gemini-3.5-flash";
  }
  return model.trim();
};

const DEFAULT_DISCLAIMER =
  "This summary is generated by MediVault AI for informational guidance only. It does not constitute a clinical medical diagnosis. Please consult a qualified doctor for interpretation, diagnosis, and treatment decisions.";

