const KNOWN_UNITS = [
  "million/cu.mm",
  "cells/cu.mm",
  "lakhs/cu.mm",
  "mm/1st hr",
  "uIU/mL",
  "ng/mL",
  "pg/mL",
  "g/dL",
  "mg/dL",
  "mmol/L",
  "ratio",
  "U/L",
  "fL",
  "pg",
  "%",
];

/**
 * Universal Laboratory File Parser
 * Extracts all clinical parameters, reference intervals, abnormal flags,
 * metadata, and pathologist interpretations directly from extracted text.
 */
export const extractLabDataFromText = (
  rawText = "",
  recordTitle = "Medical Report",
  category = "Lab Reports"
) => {
  const text = rawText || "";
  const lines = text
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.length > 0);

  let patientName = "";
  let patientAge = "";
  let patientSex = "";
  let reportId = "";
  let labName = "";
  let doctorName = "";
  let sampleType = "";
  let reportDate = "";
  let detectedReportType = "";
  let remarks = "";

  // 1. Extract Lab / Diagnostic Facility Name (top lines)
  for (let i = 0; i < Math.min(4, lines.length); i++) {
    const l = lines[i];
    if (
      /diagnostics|laboratory|hospital|clinic|pathology|imaging|healthcare|lab\b/i.test(l) &&
      !/patient|report\s*id|collected|page/i.test(l)
    ) {
      labName = l.replace(/\s*\|\s*.*$/, "").replace(/\(.*?\)/g, "").trim();
      break;
    }
  }

  // 2. Extract Patient, Doctor, and Specimen Metadata
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];

    // Patient Name
    const pMatch = l.match(
      /Patient\s*Name\s*[:\s-]*([A-Za-z.\s]+?)(?:Report\s*ID|Age|Sex|Collected|Patient\s*ID|$)/i
    );
    if (pMatch && pMatch[1].trim().length > 2 && !patientName) {
      patientName = pMatch[1].trim();
    }

    // Age / Sex
    const aMatch = l.match(
      /Age\s*(?:\/|\s*and\s*)?\s*Sex\s*[:\s-]*([0-9]+\s*(?:Years?|Yrs?|Y)?\s*(?:\/|,)?\s*(?:Male|Female|M|F|Other)?)/i
    );
    if (aMatch && !patientAge) {
      patientAge = aMatch[1].trim();
    }

    // Report ID
    const idMatch = l.match(
      /(?:Report\s*ID|Lab\s*ID|Sample\s*ID|Accession\s*(?:No|Number)?)\s*[:\s-]*([A-Za-z0-9-]+)/i
    );
    if (idMatch && !reportId) {
      reportId = idMatch[1].trim();
    }

    // Referred By Doctor
    const dMatch = l.match(
      /(?:Referred\s*By|Doctor|Consultant)\s*[:\s-]*([A-Za-z.\s]+?)(?:Sample\s*Type|Collected|Reported|$)/i
    );
    if (dMatch && dMatch[1].trim().length > 2 && !doctorName) {
      doctorName = dMatch[1].trim().replace(/\(.*?\)/g, "").trim();
    }

    // Sample / Specimen Type
    const sMatch = l.match(/Sample\s*Type\s*[:\s-]*([A-Za-z0-9\s()]+?)(?:Collected|Reported|$)/i);
    if (sMatch && !sampleType) {
      sampleType = sMatch[1].trim();
    }

    // Report Date
    const dtMatch = l.match(
      /(?:Reported\s*On|Date|Collected\s*On)\s*[:\s-]*([0-9]{1,2}-[A-Za-z]{3,9}-[0-9]{4}|[0-9]{4}-[0-9]{2}-[0-9]{2})/i
    );
    if (dtMatch && !reportDate) {
      reportDate = dtMatch[1].trim();
    }

    // Panel / Report Type
    if (!detectedReportType) {
      const panelMatch = l.match(
        /(Complete\s*Blood\s*Count(?:\s*\(CBC\))?|Differential\s*Leucocyte\s*Count|Lipid\s*Profile|Liver\s*Function\s*Test(?:\s*\(LFT\))?|Kidney\s*Function\s*Test(?:\s*\(KFT\))?|Thyroid\s*Profile|Blood\s*Glucose|Urine\s*Analysis)/i
      );
      if (panelMatch) {
        detectedReportType = panelMatch[1].trim();
      }
    }

    // Remarks / Pathologist Interpretation
    if (/Remarks|Interpretation|Impression|Conclusion/i.test(l)) {
      const remarksParts = [];
      for (let j = i + 1; j < Math.min(i + 5, lines.length); j++) {
        const nextLine = lines[j];
        if (/Dr\.|Consultant|Pathologist|End\s*of\s*Report|Page\s*[0-9]|\*\*\*/i.test(nextLine)) {
          break;
        }
        if (nextLine.length > 3) {
          remarksParts.push(nextLine.trim());
        }
      }
      if (remarksParts.length > 0 && !remarks) {
        remarks = remarksParts
          .join(" ")
          .replace(/\(Sample\s*text\s*for\s*testing\.?\)/gi, "")
          .trim();
      }
    }
  }

  // 3. Extract All Laboratory Parameters and Biomarkers
  const keyBiomarkers = [];
  const abnormalValues = [];
  const seenParameters = new Set();

  for (const rawLine of lines) {
    if (
      rawLine.startsWith("TestResult") ||
      rawLine.startsWith("Page ") ||
      rawLine.startsWith("***") ||
      rawLine.includes("SAMPLE - TEST DATA")
    ) {
      continue;
    }

    // Detect explicit flag at end of line (HIGH, LOW, CRITICAL, ABNORMAL, NORMAL)
    const flagMatch = rawLine.match(/(HIGH|LOW|CRITICAL|ABNORMAL|NORMAL)$/i);
    const explicitFlag = flagMatch ? flagMatch[1].toUpperCase() : null;
    const withoutFlag = flagMatch ? rawLine.slice(0, -flagMatch[0].length).trim() : rawLine;

    // Try known units
    for (const unit of KNOWN_UNITS) {
      const unitIdx = withoutFlag.indexOf(unit);
      if (unitIdx !== -1) {
        const beforeUnit = withoutFlag.slice(0, unitIdx).trim();
        const afterUnit = withoutFlag.slice(unitIdx + unit.length).trim();

        // Extract result number immediately preceding the unit
        const numMatch = beforeUnit.match(
          /([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]+)?|[0-9]+(?:\.[0-9]+)?)$/
        );
        if (numMatch) {
          const resultVal = numMatch[1];
          let testName = beforeUnit.slice(0, -numMatch[0].length).trim();
          testName = testName.replace(/[:\t-]+$/, "").trim();

          const normalizedParamKey = testName.toLowerCase();
          if (testName.length > 1 && !seenParameters.has(normalizedParamKey)) {
            seenParameters.add(normalizedParamKey);
            const refRange = afterUnit || "";

            let flag = explicitFlag;
            const valNum = parseFloat(resultVal.replace(/,/g, ""));

            // Determine flag if not explicitly provided
            if (!flag && refRange && !isNaN(valNum)) {
              const rangeMatch = refRange.match(
                /([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]+)?|[0-9]+(?:\.[0-9]+)?)\s*-\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]+)?|[0-9]+(?:\.[0-9]+)?)/
              );
              if (rangeMatch) {
                const min = parseFloat(rangeMatch[1].replace(/,/g, ""));
                const max = parseFloat(rangeMatch[2].replace(/,/g, ""));
                if (valNum < min) flag = "LOW";
                else if (valNum > max) flag = "HIGH";
                else flag = "Normal";
              } else if (refRange.includes("<")) {
                const maxMatch = refRange.match(/<\s*([0-9]+(?:\.[0-9]+)?)/);
                if (maxMatch) {
                  const max = parseFloat(maxMatch[1]);
                  if (valNum > max) flag = "HIGH";
                  else flag = "Normal";
                }
              } else if (refRange.includes(">")) {
                const minMatch = refRange.match(/>\s*([0-9]+(?:\.[0-9]+)?)/);
                if (minMatch) {
                  const min = parseFloat(minMatch[1]);
                  if (valNum < min) flag = "LOW";
                  else flag = "Normal";
                }
              }
            }

            const formattedFlag =
              flag === "HIGH" ? "High" : flag === "LOW" ? "Low" : flag || "Normal";
            const displayValue = `${resultVal} ${unit}`;

            if (formattedFlag === "High") {
              abnormalValues.push(
                `${testName}: ${displayValue} [HIGH] (Reference: ${refRange || "Standard"})`
              );
            } else if (formattedFlag === "Low") {
              abnormalValues.push(
                `${testName}: ${displayValue} [LOW] (Reference: ${refRange || "Standard"})`
              );
            }

            keyBiomarkers.push({
              parameter: testName,
              value: displayValue,
              normalRange: refRange || "Standard reference",
              flag: formattedFlag,
            });
          }
        }
      }
    }
  }

  // 4. Fallback search against CLINICAL_REFERENCES for missing parameters
  for (const ref of CLINICAL_REFERENCES) {
    if (seenParameters.has(ref.parameter.toLowerCase())) continue;

    for (const line of lines) {
      if (ref.pattern.test(line)) {
        const numMatch = line.match(
          /([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]+)?|[0-9]+(?:\.[0-9]+)?)\s*([a-zA-Z/%]*)/
        );
        if (numMatch) {
          const valNum = parseFloat(numMatch[1].replace(/,/g, ""));
          if (!isNaN(valNum) && valNum > 0) {
            seenParameters.add(ref.parameter.toLowerCase());
            const unit = numMatch[2] || ref.unit;
            const displayValue = `${numMatch[1]} ${unit}`.trim();

            let flag = "Normal";
            if (valNum < ref.min) {
              flag = "Low";
              abnormalValues.push(
                `${ref.parameter}: ${displayValue} [LOW] (Reference: ${ref.range})`
              );
            } else if (valNum > ref.max) {
              flag = "High";
              abnormalValues.push(
                `${ref.parameter}: ${displayValue} [HIGH] (Reference: ${ref.range})`
              );
            }

            keyBiomarkers.push({
              parameter: ref.parameter,
              value: displayValue,
              normalRange: ref.range,
              flag,
            });
            break;
          }
        }
      }
    }
  }

  // 5. Build Comprehensive Clinical Findings
  const findings = [];
  if (patientName || labName) {
    const metaDetails = [
      patientName ? `Patient: ${patientName}` : null,
      patientAge ? `(${patientAge})` : null,
      labName ? `Facility: ${labName}` : null,
      sampleType ? `Specimen: ${sampleType}` : null,
      doctorName ? `Ref. Doctor: ${doctorName}` : null,
    ]
      .filter(Boolean)
      .join(" | ");
    findings.push(metaDetails);
  }

  if (abnormalValues.length > 0) {
    findings.push(
      `Flagged Values: ${abnormalValues.length} parameter(s) outside biological reference limits (${abnormalValues
        .map((a) => a.split(":")[0])
        .join(", ")}).`
    );
  }

  const normalCount = keyBiomarkers.filter((b) => b.flag === "Normal").length;
  if (normalCount > 0) {
    findings.push(
      `Biological Reference: ${normalCount} biomarker(s) verified within normal physiological limits.`
    );
  }

  if (remarks) {
    findings.push(`Clinical Interpretation: ${remarks}`);
  }

  findings.push("Consult your consulting physician for clinical correlation and treatment decisions.");

  // 6. Build Comprehensive Clinical Summary Text
  const primaryTitle = detectedReportType || recordTitle || category || "Diagnostic Medical Report";
  let summaryText = "";

  if (abnormalValues.length > 0) {
    const abnormalList = abnormalValues
      .map((a) => {
        const firstColon = a.indexOf(":");
        if (firstColon === -1) return a;
        const name = a.slice(0, firstColon).trim();
        const details = a.slice(firstColon + 1).trim();
        return `${name} (${details.replace(/Reference:\s*/i, "Ref: ")})`;
      })
      .join(", ");

    summaryText = `Diagnostic ${primaryTitle}${patientName ? ` for ${patientName}` : ""}${
      labName ? ` from ${labName}` : ""
    }. Laboratory investigation identified ${abnormalValues.length} out-of-range parameter(s): ${abnormalList}.${
      remarks ? ` Clinical remarks noted: "${remarks}".` : ""
    } ${
      normalCount > 0
        ? `${normalCount} additional biomarkers were verified within standard physiological limits.`
        : ""
    } Please consult your physician for clinical correlation and tailored guidance.`;
  } else if (keyBiomarkers.length > 0) {
    summaryText = `Diagnostic ${primaryTitle}${patientName ? ` for ${patientName}` : ""}${
      labName ? ` from ${labName}` : ""
    }. Biological reference values for ${
      keyBiomarkers.length
    } parameter(s) were analyzed and verified within normal clinical intervals.${
      remarks ? ` Clinical remarks noted: "${remarks}".` : ""
    } Routine periodic monitoring is recommended.`;
  } else {
    const excerpt = text.length > 20 ? text.slice(0, 160).replace(/\s+/g, " ") : "";
    summaryText = `Medical report documented for ${recordTitle}${labName ? ` from ${labName}` : ""}.${
      excerpt ? ` Document excerpt: "${excerpt}...".` : ""
    } Archived securely for authorized clinical evaluation.`;
  }

  return {
    summary: summaryText,
    reportType: primaryTitle,
    patientName: patientName || null,
    patientAge: patientAge || null,
    labName: labName || null,
    doctorName: doctorName || null,
    findings,
    abnormalValues,
    keyBiomarkers,
    disclaimer: DEFAULT_DISCLAIMER,
    generatedAt: new Date(),
  };
};

/**
 * Generate Clinical AI Summary using Google Gemini API with seamless clinical parser fallback
 */
export const generateMedicalReportSummary = async (
  extractedText = "",
  recordTitle = "Medical Report",
  category = "Lab Reports"
) => {
  // Extract clinical data directly using our high-precision lab parser first
  const parsedData = extractLabDataFromText(extractedText, recordTitle, category);

  const apiKey = getApiKey();
  const rawModel = process.env.AI_MODEL || "gemini-3.5-flash";
  const model = normalizeModel(rawModel);

  // If no Gemini key or text is very minimal, return the rich parsed diagnostic data immediately
  if (
    !apiKey ||
    apiKey.trim() === "" ||
    apiKey.includes("your_") ||
    !extractedText ||
    extractedText.trim().length < 20
  ) {
    return parsedData;
  }

  const prompt = `
You are an expert clinical medical AI assistant for MediVault, a healthcare record platform.
Analyze the following extracted medical report text and produce an objective, patient-friendly, and clinically accurate structured summary.

Important instructions:
- Accurately list the patient's name, age, and diagnostic facility if mentioned.
- Identify all test parameters, their measured results, units, reference intervals, and flags (High, Low, Normal).
- Highlight all abnormal / critical values clearly.
- Include the pathologist's or lab's interpretation/remarks if present.
- Do NOT hallucinate or invent values not present in the text.
- Present this strictly as informational assistance, not a final clinical diagnosis.

Respond ONLY with a valid JSON object matching this exact schema:
{
  "summary": "Comprehensive 2-4 sentence clinical overview detailing the patient, diagnostic facility, key test results, flagged parameters with their values, and laboratory remarks.",
  "reportType": "e.g. Complete Blood Count (CBC), Lipid Profile, Liver Function Test (LFT), etc.",
  "findings": ["Array of 3 to 5 clear clinical observations and takeaways"],
  "abnormalValues": ["Array of all parameters outside normal limits, e.g. 'Haemoglobin: 11.2 g/dL [LOW] (Reference: 13.0 - 17.0)'"],
  "keyBiomarkers": [
    {
      "parameter": "Test parameter name",
      "value": "Measured value with unit (e.g. 11.2 g/dL)",
      "normalRange": "Reference range (e.g. 13.0 - 17.0 g/dL)",
      "flag": "Normal | Low | High"
    }
  ]
}

Extracted Medical Report Text:
"""
${extractedText.slice(0, 7000)}
"""
`;

  try {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      signal: AbortSignal.timeout(12000),
      body: JSON.stringify({
        contents: [
          {
            parts: [{ text: prompt }],
          },
        ],
        generationConfig: {
          temperature: 0.2,
          topK: 40,
          topP: 0.95,
        },
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.warn(
        `⚠️ [Gemini API Note ${response.status}]: Using enhanced clinical analyzer.`,
        errorText.slice(0, 150)
      );
      return parsedData;
    }

    const data = await response.json();
    const candidateText = data.candidates?.[0]?.content?.parts?.[0]?.text;

    if (!candidateText) {
      return parsedData;
    }

    // Clean JSON from code fences or trailing markdown
    let cleanedJson = candidateText.replace(/```(?:json)?/gi, "").replace(/```/g, "").trim();
    const firstBrace = cleanedJson.indexOf("{");
    const lastBrace = cleanedJson.lastIndexOf("}");
    if (firstBrace !== -1 && lastBrace !== -1) {
      cleanedJson = cleanedJson.slice(firstBrace, lastBrace + 1);
    }

    const parsed = JSON.parse(cleanedJson);

    // Merge Gemini insights with parsed biomarkers table to ensure 100% data coverage
    const combinedBiomarkers =
      Array.isArray(parsed.keyBiomarkers) && parsed.keyBiomarkers.length > 0
        ? parsed.keyBiomarkers
        : parsedData.keyBiomarkers;

    const combinedAbnormal =
      Array.isArray(parsed.abnormalValues) && parsed.abnormalValues.length > 0
        ? parsed.abnormalValues
        : parsedData.abnormalValues;

    const combinedFindings =
      Array.isArray(parsed.findings) && parsed.findings.length > 0
        ? parsed.findings
        : parsedData.findings;

    return {
      summary: parsed.summary || parsedData.summary,
      reportType: parsed.reportType || parsedData.reportType,
      findings: combinedFindings,
      abnormalValues: combinedAbnormal,
      keyBiomarkers: combinedBiomarkers,
      disclaimer: DEFAULT_DISCLAIMER,
      generatedAt: new Date(),
    };
  } catch (err) {
    console.warn("⚠️ [AI Summarization Exception]: Using enhanced clinical analyzer.", err.message);
    return parsedData;
  }
};
